*/

package fibheap

// GenericFibonacciHeap represents a generic Fibonacci heap.
type GenericFibonacciHeap struct {
	minNode *genericEntry
	size    uint
}

// Item represents an item that can be stored in the generic Fibonacci heap.
type Item interface {
	// Compare returns 1 if this item is greater than the other,
	// 0 if they are equal, and -1 if this item is less than the other.
	Compare(other Item) int
}

// genericEntry represents a node in the generic Fibonacci heap.
type genericEntry struct {
	item      Item
	parent    *genericEntry
	child     *genericEntry
	left      *genericEntry
	right     *genericEntry
	degree    int
	marked    bool
}

// NewGenericFibHeap creates a new generic Fibonacci heap.
func NewGenericFibHeap() *GenericFibonacciHeap {
	return &GenericFibonacciHeap{}
}

// Enqueue adds an item to the heap.
func (heap *GenericFibonacciHeap) Enqueue(item Item) *genericEntry {
	entry := &genericEntry{item: item}

	if heap.minNode == nil {
		// If the heap is empty, make the new node the root of a singleton tree
		entry.left = entry
		entry.right = entry
		heap.minNode = entry
	} else {
		// Add the new node to the root list
		insertRight(heap.minNode, entry)

		// Update min pointer if necessary
		if item.Compare(heap.minNode.item) < 0 {
			heap.minNode = entry
		}
	}

	heap.size++
	return entry
}

// Min returns the minimum item in the heap without removing it.
func (heap *GenericFibonacciHeap) Min() (Item, error) {
	if heap.minNode == nil {
		return nil, EmptyHeapError("Cannot access minimum of empty heap")
	}
	return heap.minNode.item, nil
}

// IsEmpty returns true if the heap is empty.
func (heap *GenericFibonacciHeap) IsEmpty() bool {
	return heap.minNode == nil
}

// Size returns the number of items in the heap.
func (heap *GenericFibonacciHeap) Size() uint {
	return heap.size
}

// DequeueMin removes and returns the minimum item from the heap.
func (heap *GenericFibonacciHeap) DequeueMin() (Item, error) {
	if heap.minNode == nil {
		return nil, EmptyHeapError("Cannot dequeue minimum of empty heap")
	}

	// Save the minimum value
	minItem := heap.minNode.item

	// Add all children of the minimum node to the root list
	if heap.minNode.child != nil {
		// Splice the children into the root list
		child := heap.minNode.child
		for {
			next := child.right
			child.parent = nil
			insertRight(heap.minNode, child)
			child = next
			if child == heap.minNode.child {
				break
			}
		}
	}

	// Remove the min node from the root list
	if heap.minNode.right == heap.minNode {
		// This was the only node
		heap.minNode = nil
	} else {
		// Remove the min node and update minNode to its right sibling
		removeFromList(heap.minNode)
		heap.minNode = heap.minNode.right
		// Consolidate trees to ensure at most one tree of each degree
		heap.consolidate()
	}

	heap.size--
	return minItem, nil
}

// consolidate ensures that there is at most one tree of each degree in the root list.
func (heap *GenericFibonacciHeap) consolidate() {
	if heap.minNode == nil {
		return
	}

	// Create a map to track degrees
	maxDegree := int(heap.size)
	degreeMap := make([]*genericEntry, maxDegree+1)

	// Collect all roots
	roots := make([]*genericEntry, 0)
	current := heap.minNode
	for {
		roots = append(roots, current)
		current = current.right
		if current == heap.minNode {
			break
		}
	}

	// Process each root
	for _, root := range roots {
		degree := root.degree

		// Handle conflicts in degree
		for degreeMap[degree] != nil {
			other := degreeMap[degree]

			// Make sure root is the smaller one
			if root.item.Compare(other.item) > 0 {
				root, other = other, root
			}

			// Remove other from root list
			removeFromList(other)

			// Make other a child of root
			makeChild(root, other)

			// Clear the degree mapping for other
			degreeMap[degree] = nil
			degree++
		}

		// Update degree mapping
		degreeMap[degree] = root
	}

	// Rebuild the root list and find the new minimum
	heap.minNode = nil
	for _, root := range degreeMap {
		if root != nil {
			if heap.minNode == nil {
				// Initialize root list
				root.left = root
				root.right = root
				heap.minNode = root
			} else {
				// Add to root list
				insertRight(heap.minNode, root)

				// Update minNode if necessary
				if root.item.Compare(heap.minNode.item) < 0 {
					heap.minNode = root
				}
			}
		}
	}
}

// insertRight inserts newNode to the right of node.
func insertRight(node, newNode *genericEntry) {
	newNode.right = node.right
	newNode.left = node
	node.right.left = newNode
	node.right = newNode
}

// removeFromList removes a node from the doubly-linked list.
func removeFromList(node *genericEntry) {
	node.left.right = node.right
	node.right.left = node.left
}

// makeChild makes child a child of parent.
func makeChild(parent, child *genericEntry) {
	// Remove child from its current position
	removeFromList(child)

	// Add child to parent's child list
	if parent.child == nil {
		parent.child = child
		child.left = child
		child.right = child
	} else {
		insertRight(parent.child, child)
	}

	child.parent = parent
	parent.degree++
	child.marked = false
}
