package fibheap

import (
	"testing"

	"github.com/stretchr/testify/assert"
)

// testItem implements Item interface for testing
type testItem int

func (ti testItem) Compare(other Item) int {
	oti := other.(testItem)
	if ti > oti {
		return 1
	} else if ti == oti {
		return 0
	}
	return -1
}

func TestGenericFibHeapEnqueueDequeue(t *testing.T) {
	heap := NewGenericFibHeap()

	// Test enqueue
	entry := heap.Enqueue(testItem(5))
	assert.NotNil(t, entry)

	// Test min
	min, err := heap.Min()
	assert.NoError(t, err)
	assert.Equal(t, testItem(5), min)

	// Test size
	assert.Equal(t, uint(1), heap.Size())

	// Test dequeue
	item, err := heap.DequeueMin()
	assert.NoError(t, err)
	assert.Equal(t, testItem(5), item)

	// Test empty
	assert.True(t, heap.IsEmpty())
	assert.Equal(t, uint(0), heap.Size())
}

func TestGenericFibHeapMultipleItems(t *testing.T) {
	heap := NewGenericFibHeap()

	// Enqueue items in random order
	heap.Enqueue(testItem(10))
	heap.Enqueue(testItem(3))
	heap.Enqueue(testItem(7))
	heap.Enqueue(testItem(1))

	// Should dequeue in sorted order
	item, err := heap.DequeueMin()
	assert.NoError(t, err)
	assert.Equal(t, testItem(1), item)

	item, err = heap.DequeueMin()
	assert.NoError(t, err)
	assert.Equal(t, testItem(3), item)

	item, err = heap.DequeueMin()
	assert.NoError(t, err)
	assert.Equal(t, testItem(7), item)

	item, err = heap.DequeueMin()
	assert.NoError(t, err)
	assert.Equal(t, testItem(10), item)

	assert.True(t, heap.IsEmpty())
}

func TestGenericFibHeapEmptyOperations(t *testing.T) {
	heap := NewGenericFibHeap()

	// Test min on empty heap
	_, err := heap.Min()
	assert.Error(t, err)
	assert.IsType(t, EmptyHeapError(""), err)

	// Test dequeue on empty heap
	_, err = heap.DequeueMin()
	assert.Error(t, err)
	assert.IsType(t, EmptyHeapError(""), err)
}
